/**
 * dsh-session-doctor — 会话医生
 * 诊断、解卡、读取 DeepSeek Harness 会话的插件:
 *   - list_sessions     列出所有会话(标题、在线状态、agent status、排队消息数)
 *   - read_session      读取指定会话的对话记录
 *   - session_status    诊断一个会话的 agent 是否卡死
 *   - session_recover   解卡:中止卡住的活动、保留 inbox 排队消息
 * Host 半区,纯 JS,无构建。
 */
import { defineTool } from '@deepseek-ai/dsh-tools'

export const name = 'dsh-session-doctor'
export const inject = ['agents', 'tools', 'sessionQuery', 'agentLoop']

/** 从 content blocks 中提取可见文本。 */
function textOf(blocks) {
  if (!Array.isArray(blocks)) return ''
  return blocks
    .filter((b) => b && b.type === 'text' && typeof b.text === 'string')
    .map((b) => b.text)
    .join('\n')
}

/** 从 content blocks 中提取文本块数组(含 reasoning)。 */
function blocksOf(blocks) {
  if (!Array.isArray(blocks)) return []
  return blocks
    .filter((b) => b && typeof b.text === 'string')
    .map((b) => ({ type: b.type, text: b.text }))
}

/** 当前 live agent 状态摘要。 */
function liveInfo(agent) {
  if (agent === undefined) return { live: false }
  return {
    live: true,
    status: agent.status,
    pendingTurn: agent.inbox.nextTurn.length,
    pendingStep: agent.inbox.nextStep.length,
  }
}

export function apply(ctx) {
  let seq = 0
  const messageId = () => `xsess-${Date.now().toString(36)}-${(seq++).toString(36)}`

  const lastEventOf = async (sessionId) => {
    const evs = await ctx.sessionQuery.listEvents(sessionId)
    return evs.length ? evs[evs.length - 1] : null
  }

  // ── list_sessions:列出所有会话 ──
  ctx.tools.register(defineTool({
    name: 'list_sessions',
    description: '列出本机所有会话(标题、id、在线状态、agent 运行状态、工作目录),用于查找要查看或发送消息的会话。',
    parameters: {},
    output: {
      schema: { type: 'json' },
      render: (_args, value) => [{ type: 'text', text: JSON.stringify(value, null, 2) }],
    },
    async execute() {
      const records = await ctx.sessionQuery.listSessions()
      const ids = records.map((r) => r.header.id)
      const titleResults = await ctx.sessionQuery.readTitleSnapshots(ids)
      const titleById = new Map()
      for (const tr of titleResults) {
        if (tr.status === 'fulfilled' && tr.value.title) {
          titleById.set(tr.sessionId, tr.value.title.title)
        }
      }
      return {
        count: records.length,
        sessions: records.map((r) => ({
          id: r.header.id,
          title: titleById.get(r.header.id) ?? '',
          persisted: r.persisted,
          cwd: r.header.cwd ?? '',
          createdAt: r.header.createdAt,
          ...liveInfo(ctx.agents.get(r.header.id)),
        })),
      }
    },
  }))

  // ── read_session:读取一个会话的消息 ──
  ctx.tools.register(defineTool({
    name: 'read_session',
    description: '读取指定会话的对话记录(用户与助手消息文本),按时间顺序返回。用于查看另一个会话的任务进度。',
    parameters: {
      session_id: { type: 'string', required: true, description: '目标会话 id(来自 list_sessions)' },
      limit: { type: 'number', description: '最多返回多少条消息,默认 100,最大 500' },
    },
    output: {
      schema: { type: 'json' },
      render: (_args, value) => [{ type: 'text', text: JSON.stringify(value, null, 2) }],
    },
    async execute(args) {
      const limit = Math.min(Math.max(Number(args.limit ?? 100) || 100, 1), 500)
      const snapshot = await ctx.sessionQuery.readSession(args.session_id)
      const titleObs = await ctx.sessionQuery.readTitleSnapshot(args.session_id)
      const messages = []
      for (const ev of snapshot.events) {
        if (ev.type === 'user/message') {
          const text = textOf(ev.data.content)
          if (text) messages.push({ role: 'user', seq: ev.seq, time: ev.time, text })
        } else if (ev.type === 'assistant/message') {
          const text = textOf(ev.data.message && ev.data.message.content)
          if (text) messages.push({ role: 'assistant', seq: ev.seq, time: ev.time, text })
        }
      }
      const recent = messages.slice(-limit)
      return {
        session_id: args.session_id,
        title: titleObs.title ? titleObs.title.title : '',
        total_messages: messages.length,
        live: liveInfo(ctx.agents.get(args.session_id)),
        messages: recent,
      }
    },
  }))

  // ── session_status:诊断 agent 状态 ──
  ctx.tools.register(defineTool({
    name: 'session_status',
    description: '诊断一个会话的 agent 运行状态:是否在线、status(running/idle)、inbox 排队消息数。当消息投递后对方迟迟不处理时,用它确认是否卡死。',
    parameters: {
      session_id: { type: 'string', required: true, description: '目标会话 id' },
    },
    output: {
      schema: { type: 'json' },
      render: (_args, value) => [{ type: 'text', text: JSON.stringify(value, null, 2) }],
    },
    async execute(args) {
      const info = liveInfo(ctx.agents.get(args.session_id))
      const lastEvent = await lastEventOf(args.session_id)
      const last = lastEvent ? { seq: lastEvent.seq, type: lastEvent.type, time: lastEvent.time } : null
      if (!info.live) {
        return { session_id: args.session_id, live: false, last_event: last, note: 'agent 不在线;消息会通过持久化恢复投递' }
      }
      return {
        session_id: args.session_id,
        ...info,
        last_event: last,
        note: info.status === 'running'
          ? 'agent 正在运行中(running),可能卡在某个工具调用;若长时间无进展可视为卡死,可用 session_recover 解卡'
          : 'agent 空闲(idle),inbox 消息会尽快处理',
      }
    },
  }))

  // ── session_recover:解卡 ──
  ctx.tools.register(defineTool({
    name: 'session_recover',
    description: '解卡一个卡死的会话:对 running 状态的 agent 执行取消(中止卡住的活动,保留 inbox 排队消息,agent 回到 idle 后自动处理排队消息)。用于修复卡在未完成工具调用上的 agent。',
    parameters: {
      session_id: { type: 'string', required: true, description: '目标会话 id' },
    },
    output: {
      schema: { type: 'json' },
      render: (_args, value) => [{ type: 'text', text: JSON.stringify(value, null, 2) }],
    },
    async execute(args) {
      const agent = ctx.agents.get(args.session_id)
      if (agent === undefined) {
        return { session_id: args.session_id, recovered: false, note: 'agent 不在线,无需解卡' }
      }
      if (agent.status !== 'running') {
        return { session_id: args.session_id, recovered: false, status: agent.status, note: 'agent 空闲,无需解卡' }
      }
      const before = {
        status: agent.status,
        pendingTurn: agent.inbox.nextTurn.length,
        pendingStep: agent.inbox.nextStep.length,
      }
      // 中止当前卡住的活动,但保留 inbox 排队消息(keepInbox)
      agent.cancel({ kind: 'user' }, { keepInbox: true })
      return {
        session_id: args.session_id,
        recovered: true,
        before,
        note: '已发送取消信号(keepInbox: true);卡住的活动被中止,排队消息将在 agent 回到 idle 后处理',
      }
    },
  }))

  // ── send_session_message:向目标会话发送消息 ──
  ctx.tools.register(defineTool({
    name: 'send_session_message',
    description: '向另一个会话发送一条用户消息,对方 agent 会作为新的一轮处理。目标会话在线时直接投递;仅持久化时自动恢复后投递。',
    parameters: {
      session_id: { type: 'string', required: true, description: '目标会话 id(来自 list_sessions)' },
      text: { type: 'string', required: true, description: '要发送的消息文本' },
    },
    output: {
      schema: { type: 'json' },
      render: (_args, value) => [{ type: 'text', text: JSON.stringify(value, null, 2) }],
    },
    async execute(args) {
      const sessionId = args.session_id
      const text = String(args.text ?? '').trim()
      if (!text) throw new Error('text 不能为空')
      const message = {
        id: messageId(),
        role: 'user',
        content: [{ type: 'text', text }],
        source: { kind: 'plugin', plugin: 'cross-session', form: 'relay' },
      }
      const live = ctx.agents.get(sessionId)
      if (live !== undefined) {
        live.followup(message)
        return {
          delivered: true,
          mode: 'live',
          session_id: sessionId,
          message_id: message.id,
          target_status: live.status,
          note: live.status === 'running'
            ? '目标 agent 处于 running 状态;消息已进入 inbox 排队。若 agent 卡死将不会处理,先用 session_status 诊断,再用 session_recover 解卡'
            : undefined,
        }
      }
      const handle = await ctx.agentLoop.resume(ctx, { resumeSessionId: sessionId })
      handle.agent.followup(message)
      return { delivered: true, mode: 'resumed', session_id: sessionId, message_id: message.id, note: '目标会话已从持久化恢复,消息已投递' }
    },
  }))
}
